        static void Require(bool b,string why){if(!b)throw new Exception(why);}
        static T Throws<T>(Action a)where T:Exception{try{a();}catch(T e){return e;}throw new Exception("Expected "+typeof(T).Name);}
        public static BattleBuild.Report Run()
        {
            var r=new BattleBuild.Report{passed=true,unityVersion=Application.unityVersion,limitations="Original TopInfo owned load/outlets/Awake/profile/account/events/icons/disposal and BaseUI Await, sharing actual account/UserInfo/data-pool/effect runtime. Rank score, Match record, avatar platform/download, UserInfoUI open destination and sprite loader remain required fixture endpoints. Native open/close/storage/resource verification separate; complete production Main/platform/Player not claimed."};
            Action<string,Action> check=(id,a)=>{try{a();r.checks.Add(new BattleBuild.Check{id="top-info-page-"+id,result="pass"});}catch(Exception e){r.passed=false;r.checks.Add(new BattleBuild.Check{id="top-info-page-"+id,result="fail",detail=e.ToString()});}};
            check("deferred-page-original25-outlets-awake-and-separate-icon-wait",()=>{using(var f=new Fixture()){var args=new object[]{7};var p=f.Open(args);Require(p.GameObject==null&&p.Lifetime.Arguments==args&&f.Provider.RefCount==1&&p.GoldEffectId==-1&&p.DiamondEffectId==-1,"original deferred ownership/ctor fields");f.CompleteLoad();Require(p.OutletCount==25&&p.UserRoot.activeSelf&&!p.MatchUserRoot.activeSelf&&!p.StaminaRoot.activeSelf&&p.NameRed!=null,"source Awake visibility/red binding");Require(p.GoldText.text=="0"&&p.DiamondsText.text=="0"&&p.NameText.text==f.User.Name&&p.ScoreText.text=="1.23","actual local/user records and recovered score formatting");Require(!p.IconInitialization.IsCompleted&&f.Effects.Module.Effects.Count==0&&f.ReadyEvents==0,"native readiness is a separate wait");f.Waits[0].Complete();Require(p.IconInitialization.IsCompleted&&f.Effects.Module.Get(p.GoldEffectId).Config.id==1007&&f.Effects.Module.Get(p.DiamondEffectId).Config.id==1019&&f.ReadyEvents==1,"ready before original two ordered effects");}});
            check("real-tool-economy-refresh-and-server-record-replacement",()=>{using(var f=new Fixture()){f.Start();f.Account.Account.Tool.ToolChange(1001,17,true,"",true);Require(f.Page.GoldText.text=="17"&&f.Account.Account.Local.GoldNum==17,"actual tool callback reaches real top Text");f.Account.Account.Local.UpdateDataCallBack("{\"goldNum\":123,\"diamondsNum\":9}");f.Page.RefreshInfo();Require(f.Page.GoldText.text=="123"&&f.Page.DiamondsText.text=="9","captured manager reads current replacement record");f.Account.Statistics.Pool.Managers.Remove(4119);f.Page.RefreshInfo();Require(f.Page.GoldText.text=="123"&&ReferenceEquals(f.Page.LocalData,f.Account.Account.Local),"manager captured in Awake; later pool removal does not re-resolve");}});
            check("loadstarting-refresh-nickname-red-score-and-distinct-sprite-fields",()=>{using(var f=new Fixture()){f.Start();f.User.Manager.Name="You";f.Services.RankScore=()=>150;f.Sprites.Clear();f.Messages.SendMessage("LoadStartingUI",new object[]{"ignored"});Require(f.Page.NameText.text=="You"&&f.Page.NameRed.activeSelf&&f.Page.ScoreText.text=="1","source nickname equality and last-zero score rule");Require(f.Sprites.Count==2&&f.Sprites[0].image==f.Page.HeadIcon&&f.Sprites[0].name==f.User.GetHeadportConfig().icon&&f.Sprites[0].atlas==f.User.GetHeadportConfig().atlas&&f.Sprites[1].image==f.Page.HeadBoxIcon&&f.Sprites[1].atlas==f.User.GetHeadBoxConfig().atlas&&f.Sprites.All(s=>s.mode==0),"original head/frame config field mapping");f.User.Manager.Name="renamed";f.Messages.SendMessage("LoadStartingUI");Require(!f.Page.NameRed.activeSelf&&f.Page.NameText.text=="renamed","later live profile refresh");}});
            check("profile-reentry-captures-name-but-rereads-current-config",()=>{using(var f=new Fixture()){f.Start();f.User.Manager.Name="before";f.Services.Language=key=>{f.User.Manager.Name="after";f.User.Manager.Data.headportId=2;return "before";};f.Sprites.Clear();f.Page.RefreshProfile();Require(f.Page.NameText.text=="before"&&f.Page.NameRed.activeSelf&&f.Sprites[0].name==f.Config.dicHeadport[2].icon&&f.User.Name=="after","nickname evaluated before language; later config follows mutated account");}});
            check("sprite-failure-preserves-earlier-profile-updates-and-skips-frame",()=>{using(var f=new Fixture()){f.Start();f.User.Manager.Name="new";f.Services.RankScore=()=>999;f.Sprites.Clear();f.SpriteRead=()=>throw new InvalidOperationException();Throws<InvalidOperationException>(f.Page.RefreshProfile);Require(f.Page.NameText.text=="new"&&f.Page.ScoreText.text=="9.99"&&f.Sprites.Count==1,"failure after labels and head request, before frame request");}});
            check("both-user-pointers-request-empty-args-without-button-message",()=>{using(var f=new Fixture()){f.Start();int n=0;f.Messages.AddListener("GF_UIButtonClick",a=>n++);OutgameUiPointerClick.Get(f.Page.UserRoot).OnPointerClick(null);OutgameUiPointerClick.Get(f.Page.MatchUserRoot).OnPointerClick(null);Require(f.UserOpens==2&&n==0,"both GameObject source click overloads");}});
            check("auth-null-empty-single-null-element-and-gate-order",()=>{using(var f=new Fixture()){f.Start();f.Page.AvatarAuthorized(null);f.Page.AvatarAuthorized(Array.Empty<object>());Throws<IndexOutOfRangeException>(()=>f.Page.AvatarAuthorized(new object[]{"a"}));Throws<NullReferenceException>(()=>f.Page.AvatarAuthorized(new object[]{null,"b"}));Throws<NullReferenceException>(()=>f.Page.AvatarAuthorized(new object[]{"",null}));f.Page.AvatarAuthorized(new object[]{"","b"});Require(!f.CurrentPlayer.HasWechatInfo&&f.UserSaves==0,"both ToString calls occur before empty gate; source length1 failure retained");}});
            check("auth-uses-platform-values-and-orders-download-name-save",()=>{using(var f=new Fixture()){f.Start();var originalName=f.User.Name;f.Save=()=>{Require(f.CurrentPlayer.HasWechatInfo&&f.Page.MatchNameText.text=="platform-nickname"&&f.AvatarRequested=="platform-avatar","record/download/name before save");};f.Messages.SendMessage("Avatar_Refresh_OnAuth",new object[]{"event-name","event-url"});Require(f.CurrentPlayer.Nickname=="platform-nickname"&&f.CurrentPlayer.AvatarUrl=="platform-avatar"&&f.User.Name==originalName&&f.UserSaves==1,"platform projection updates Match, separate UserInfo unchanged");var sprite=f.Page.HeadIcon.sprite;f.AvatarCallback(sprite);Require(f.Page.WechatHead.sprite==sprite,"actual callback target");}});
            check("auth-captures-target-before-getter-and-reresolves-current-player",()=>{using(var f=new Fixture()){f.Start();var old=f.CurrentPlayer;var next=new Player{Nickname="replacement"};f.Services.MyNickname=()=>{f.CurrentPlayer=next;return "returned";};f.Services.MyAvatarUrl=()=>"";f.Page.AvatarAuthorized(new object[]{"a","b"});Require(old.HasWechatInfo&&old.Nickname=="returned"&&!next.HasWechatInfo&&next.AvatarUrl==""&&f.Page.MatchNameText.text=="replacement"&&f.AvatarRequested==null,"nickname captured target; later fields/rereads use replacement; empty URL skips source");}});
