            check("disposal-first-effect-failure-stops-second-resolution",()=>{using(var f=new Fixture()){f.Start();int calls=0;var p=f.Page;f.Services.Effects=()=>{calls++;throw new InvalidOperationException();};Throws<InvalidOperationException>(p.Dispose);Require(calls==1&&f.Effects.Module.Effects.Count==2,"failure leaves both effects and stops second module resolution");f.Messages.SendMessage("Avatar_Refresh_OnAuth",new object[]{"a","b"});Require(f.UserSaves==0,"listeners already removed before close failure");f.Services.Effects=()=>f.Effects.Module;}});
            check("late-icon-continuation-after-direct-dispose-is-not-cancelled",()=>{using(var f=new Fixture()){f.Open();f.CompleteLoad();f.Page.Dispose();Require(f.Effects.Module.Effects.Count==0,"initial -1 closes no effect");f.Waits[0].Complete();Require(f.Effects.Module.Effects.Count==2&&!f.Page.Lifetime.IsDisposed,"source pending continuation can create after direct Dispose");}});
            check("second-icon-failure-retains-first-id-and-earlier-effects",()=>{using(var f=new Fixture()){f.Start();int oldGold=f.Page.GoldEffectId,oldDiamond=f.Page.DiamondEffectId,calls=0;f.Services.Effects=()=>{if(++calls==2)throw new InvalidOperationException();return f.Effects.Module;};var task=f.Page.InitializeIconsAsync();f.Waits.Last().Complete();Throws<InvalidOperationException>(()=>task.GetAwaiter().GetResult());Require(f.Page.GoldEffectId!=oldGold&&f.Page.DiamondEffectId==oldDiamond&&f.Effects.Module.Get(oldGold)!=null&&f.Effects.Module.Effects.Count==3,"first Show published before second failure; no rollback or older-id close");f.Services.Effects=()=>f.Effects.Module;}});
            check("auth-userdata-save-failure-prevents-pool-save-after-name",()=>{using(var f=new Fixture()){f.Start();string before=f.Account.Stored("LocalDataManager");f.Account.Services.Profile.inventory.goldNum=91;f.Save=()=>throw new InvalidOperationException();Throws<InvalidOperationException>(()=>f.Page.AvatarAuthorized(new object[]{"a","b"}));Require(f.Page.MatchNameText.text=="platform-nickname"&&f.UserSaves==1&&f.Account.Stored("LocalDataManager")==before,"user prefs failure stops pool persistence after Match/text changes");}});
            check("real-uicontrol-currency-cache-follows-owned-deferred-page",()=>{using(var f=new Fixture()){var registry=f.Account.Page.Data.Registry;var control=new OutgameUiControl(null,registry,()=>f.Messages,new OutgameUiControlGlobals(),null,()=>f.Open(),null,null,null);control.ShowTopInfoUI();Require(control.TopInfo==f.Page&&control.GoldText==null&&f.Loads.Count==1,"actual UIControl holds page before async outlet init");f.CompleteLoad();f.Page.OpenParts();f.Waits[0].Complete();Require(control.GoldText==f.Page.GoldText&&control.DiamondsText==f.Page.DiamondsText,"lazy actual cache retries after outlets load");f.Page.SetVisible(false);control.ShowTopInfoUI();Require(f.Page.Visible&&f.Page.GoldRoot.activeSelf&&f.Page.DiamondRoot.activeSelf&&f.Loads.Count==0,"source UIControl reuse/show/renderer route uses same owned page");}});
            check("ready-predicate-null-disposed-live-and-callback-destruction",()=>{var bus=new OutgameMessageDispatcher();var life=new OutgameUiLifetime(null,()=>{},UnityEngine.Object.DestroyImmediate);var owner=new object();var ready=new OutgameUiReadyAwait(life,owner,()=>bus);int notices=0;Require(!ready.IsReady(),"null live waits");life.MarkDisposed();Require(ready.IsReady(),"null disposed completes without message");var go=new GameObject("ready");life.Attach(go,null);bus.AddListener("GF_LoadUIOver",a=>{Require(ReferenceEquals(a[0],owner),"original page identity");notices++;UnityEngine.Object.DestroyImmediate(go);});Require(ready.IsReady()&&notices==1&&!life.Transform,"live transform even disposed emits and returns true after callback destroys it");Require(ready.IsReady()&&notices==1,"Unity null disposed branch emits no second notice");});
            check("empty-refresh-and-missing-local-manager-retain-prefab-currency",()=>{using(var f=new Fixture()){f.Account.Statistics.Pool.Managers.Remove(4119);f.Open();f.CompleteLoad();string before=f.Page.GoldText.text;Require(f.Page.LocalData==null&&before=="19960","source missing local manager returns null and keeps original prefab text");f.Page.Refresh();Require(f.Page.GoldText.text==before,"original virtual Refresh empty");f.Waits[0].Complete();}});
            return r;
        }
